import { describe, expect, test } from 'vitest';

import {
  DARK_SHARE_BAR_COLORS,
  SHARE_STATE_KINDS,
  describeShareState,
  fadeColor,
  shareBarColorsFrom,
  shareBarFill,
  shareBarWidth,
  shareStateToggle,
  shareStateWord,
} from './shareState';

describe('the words', () => {
  test('a file that is here and available is Active, in green, with no bar', () => {
    expect(describeShareState({ kind: 'active' })).toMatchObject({
      label: 'Active',
      shortLabel: 'Active',
      tone: 'good',
      bar: null,
      dim: false,
      toggle: null,
    });
  });

  test('a download always carries its number, even at the very start', () => {
    expect(describeShareState({ kind: 'downloading', percent: 47.6 }).label).toBe('Downloading 48%');
    expect(describeShareState({ kind: 'downloading', percent: 0 }).label).toBe('Downloading 0%');
    expect(describeShareState({ kind: 'downloading', percent: null }).label).toBe('Downloading 0%');
    expect(describeShareState({ kind: 'downloading', percent: 140 }).label).toBe('Downloading 100%');
  });

  test('someone taking the file from this device is Sharing, with a number when it is known', () => {
    expect(describeShareState({ kind: 'sharing', percent: 12 }).label).toBe('Sharing 12%');
    expect(describeShareState({ kind: 'sharing' }).label).toBe('Sharing');
  });

  test('waiting and paused show a number only once something has arrived', () => {
    expect(describeShareState({ kind: 'waiting', percent: 23 }).label).toBe('Waiting 23%');
    expect(describeShareState({ kind: 'waiting', percent: 0 }).label).toBe('Waiting');
    expect(describeShareState({ kind: 'waiting' }).label).toBe('Waiting');
    expect(describeShareState({ kind: 'paused', percent: 23 }).label).toBe('Paused 23%');
    expect(describeShareState({ kind: 'paused', percent: 0 }).label).toBe('Paused');
  });

  test('in a grid a download, a wait and a pause drop the number; an upload keeps it', () => {
    expect(describeShareState({ kind: 'downloading', percent: 37 }).shortLabel).toBe('Downloading');
    expect(describeShareState({ kind: 'waiting', percent: 37 }).shortLabel).toBe('Waiting');
    expect(describeShareState({ kind: 'paused', percent: 37 }).shortLabel).toBe('Paused');
    expect(describeShareState({ kind: 'sharing', percent: 12 }).shortLabel).toBe('Sharing 12%');
  });

  test('a state that needs the person says what is wrong, in red', () => {
    expect(describeShareState({ kind: 'attention', note: 'Not enough space' })).toMatchObject({
      label: 'Not enough space',
      tone: 'bad',
    });
    // No note given: still words, never an empty line.
    expect(describeShareState({ kind: 'attention' }).label).toBe('Needs you');
  });

  test('it is one state, never a chain of them, and never says paused for a wait', () => {
    for (const kind of SHARE_STATE_KINDS) {
      const view = describeShareState({ kind, percent: 23, note: 'Not enough space' });
      expect(view.label).not.toMatch(/[·•|(]/);
      expect(view.label.length).toBeGreaterThan(0);
      expect(shareStateWord(kind).length).toBeGreaterThan(0);
    }
    expect(describeShareState({ kind: 'waiting', percent: 23 }).label).not.toMatch(/paused/i);
  });
});

describe('the colours', () => {
  test('green is finished, amber is not finished, grey is off, red needs you', () => {
    const tone = (kind: (typeof SHARE_STATE_KINDS)[number]) => describeShareState({ kind }).tone;
    expect(tone('active')).toBe('good');
    for (const kind of ['sharing', 'downloading', 'starting', 'waiting', 'paused', 'choose'] as const) {
      expect(tone(kind)).toBe('busy');
    }
    expect(tone('inactive')).toBe('plain');
    expect(tone('attention')).toBe('bad');
  });

  test('only a share that is switched off is drawn fainter', () => {
    for (const kind of SHARE_STATE_KINDS) {
      expect(describeShareState({ kind, percent: 50 }).dim).toBe(kind === 'inactive');
    }
  });
});

describe('the progress bar', () => {
  test('moving for a download or an upload, holding for a wait, stopped for a pause', () => {
    expect(describeShareState({ kind: 'downloading', percent: 25 }).bar).toEqual({ look: 'moving', value: 0.25 });
    expect(describeShareState({ kind: 'sharing', percent: 50 }).bar).toEqual({ look: 'moving', value: 0.5 });
    expect(describeShareState({ kind: 'starting', percent: 23 }).bar).toEqual({ look: 'moving', value: 0.23 });
    expect(describeShareState({ kind: 'waiting', percent: 23 }).bar).toEqual({ look: 'holding', value: 0.23 });
    expect(describeShareState({ kind: 'paused', percent: 23 }).bar).toEqual({ look: 'stopped', value: 0.23 });
  });

  test('a download that has not moved yet still has its (empty) bar', () => {
    expect(describeShareState({ kind: 'downloading', percent: null }).bar).toEqual({ look: 'moving', value: 0 });
    expect(describeShareState({ kind: 'waiting', percent: 0 }).bar).toEqual({ look: 'holding', value: 0 });
  });

  test('no bar where there is nothing to count', () => {
    for (const kind of ['active', 'inactive', 'choose', 'attention'] as const) {
      expect(describeShareState({ kind, percent: 50 }).bar).toBeNull();
    }
    expect(describeShareState({ kind: 'sharing' }).bar).toBeNull();
    expect(describeShareState({ kind: 'waiting' }).bar).toBeNull();
  });

  test('the fill is a gradient only while moving', () => {
    const c = DARK_SHARE_BAR_COLORS;
    expect(shareBarFill('moving')).toEqual([c.from, c.to]);
    expect(shareBarFill('holding')).toEqual([c.holding, c.holding]);
    expect(shareBarFill('stopped')).toEqual([c.stopped, c.stopped]);
    expect(c.from).not.toBe(c.to);
  });

  test("an app's own amber and green make the bar, so the bar and the words agree", () => {
    const bar = shareBarColorsFrom({ busy: '#f59e0b', good: '#a8cf3a' });
    expect(bar.from).toBe('#f59e0b');
    expect(bar.to).toBe('#a8cf3a');
    expect(bar.holding).toBe('rgba(245,158,11,0.55)');
    expect(fadeColor('#fa0', 0.5)).toBe('rgba(255,170,0,0.5)');
    // Not a hex colour: handed back untouched rather than guessed at.
    expect(fadeColor('rgb(1,2,3)', 0.5)).toBe('rgb(1,2,3)');
  });

  test('the width is held between nothing and the whole track', () => {
    expect(shareBarWidth(0.4)).toBe(0.4);
    expect(shareBarWidth(-1)).toBe(0);
    expect(shareBarWidth(7)).toBe(1);
    expect(shareBarWidth(Number.NaN)).toBe(0);
  });
});

describe('pause and resume', () => {
  test('anything that may still run by itself can be paused', () => {
    expect(shareStateToggle('downloading')).toBe('pause');
    expect(shareStateToggle('starting')).toBe('pause');
    expect(shareStateToggle('waiting')).toBe('pause');
  });

  test('only a paused download can be resumed', () => {
    expect(shareStateToggle('paused')).toBe('resume');
  });

  test('nothing else has the button', () => {
    for (const kind of ['active', 'sharing', 'inactive', 'choose', 'attention'] as const) {
      expect(shareStateToggle(kind)).toBeNull();
    }
  });
});
